import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.Decn_Lan.js";const r="/my-website/assets/db_architecture.png",m=JSON.parse('{"title":"Relational Database Engine","description":"Extending a basic database system with B+Tree indices, optimized join algorithms, query optimization, multigranularity locking, and ARIES-style recovery.","frontmatter":{"title":"Relational Database Engine","date":"2026-01-17T00:00:00.000Z","description":"Extending a basic database system with B+Tree indices, optimized join algorithms, query optimization, multigranularity locking, and ARIES-style recovery."},"headers":[],"relativePath":"blog/db-engine.md","filePath":"blog/db-engine.md","lastUpdated":null}'),o={name:"blog/db-engine.md"};function s(l,e,c,d,g,p){return t(),i("div",null,[...e[0]||(e[0]=[n('<p class="post-eyebrow">// design doc · systems</p><h1 id="mini-relational-database-engine" tabindex="-1">Mini Relational Database Engine <a class="header-anchor" href="#mini-relational-database-engine" aria-label="Permalink to &quot;Mini Relational Database Engine&quot;">​</a></h1><p class="post-lede">Extending a basic database system with B+Tree indices, optimized join algorithms, query optimization, multigranularity locking, and ARIES-style recovery.</p><div class="readouts"><div><b>603 → 8</b><span>I/Os after picking sort-merge join</span></div><div><b>5</b><span>lock modes in multi-granularity 2PL</span></div><div><b>3</b><span>ARIES phases: analysis, redo, undo</span></div></div><p><a href="https://github.com/CleverAutoman/relational-db-engine" target="_blank" rel="noreferrer">Source on GitHub</a></p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>This project is based on a minimal relational database implementation that supports executing simple transactions in serial. The system was incrementally extended to support key features expected in modern database systems, with a focus on correctness, performance, and modular design.</p><p>The primary goal of this project is to explore the design and implementation of core database internals, including storage indexing, query execution strategies, transaction concurrency, and crash recovery.</p><h2 id="system-architecture" tabindex="-1">System Architecture <a class="header-anchor" href="#system-architecture" aria-label="Permalink to &quot;System Architecture&quot;">​</a></h2><p>The system is composed of the following core components:</p><ul><li><strong>Storage Layer</strong>: Manages pages, records, and disk I/O.</li><li><strong>Index Layer</strong>: Provides clustered B+Tree indices for efficient record access.</li><li><strong>Query Execution Layer</strong>: Implements relational operators and join algorithms.</li><li><strong>Transaction &amp; Concurrency Layer</strong>: Handles locking and transaction isolation.</li><li><strong>Recovery Layer</strong>: Ensures durability and correctness in the presence of failures.</li></ul><h3 id="architecture-diagram" tabindex="-1">Architecture Diagram <a class="header-anchor" href="#architecture-diagram" aria-label="Permalink to &quot;Architecture Diagram&quot;">​</a></h3><p><img src="'+r+'" alt="Database architecture diagram"></p><h2 id="implemented-features" tabindex="-1">Implemented Features <a class="header-anchor" href="#implemented-features" aria-label="Permalink to &quot;Implemented Features&quot;">​</a></h2><ul><li>Clustered B+Tree indexing</li><li>Multiple join algorithms with cost-based selection</li><li>Query optimization for multi-table joins</li><li>Multi-granularity locking for concurrent transactions</li><li>ARIES-style logging and crash recovery</li></ul><h2 id="b-tree-index" tabindex="-1">B+ Tree Index <a class="header-anchor" href="#b-tree-index" aria-label="Permalink to &quot;B+ Tree Index&quot;">​</a></h2><ul><li>Implemented a <strong>clustered B+Tree index</strong> to support efficient point lookups and range scans.</li><li>Supports core index operations including search, insert, and delete.</li><li>Handles node split and merge operations to maintain tree balance.</li><li>Integrated with the query execution engine to optimize index-based access paths.</li></ul><h2 id="join-algorithms-and-query-optimization" tabindex="-1">Join Algorithms and Query Optimization <a class="header-anchor" href="#join-algorithms-and-query-optimization" aria-label="Permalink to &quot;Join Algorithms and Query Optimization&quot;">​</a></h2><p>The following join algorithms are implemented and evaluated:</p><ul><li><strong>Nested Loop Join</strong></li><li><strong>Hash Join</strong></li><li><strong>Sort-Merge Join</strong></li></ul><p>Through the design and implementation of these algorithms, I gained a deep understanding of their characteristics and how they affect performance under different workloads. Each algorithm is selected based on its performance behavior across varying data sizes and join predicates. Through benchmarking, <strong>sort-merge join</strong> was chosen for multi-table join workloads, reducing I/O operations from <strong>603 to 8</strong> compared to the baseline implementation.</p><h3 id="query-optimization" tabindex="-1">Query Optimization <a class="header-anchor" href="#query-optimization" aria-label="Permalink to &quot;Query Optimization&quot;">​</a></h3><p>The query optimizer uses a <strong>cost-based, dynamic programming approach</strong> to identify efficient execution plans.</p><p>For single-table access, the optimizer selects the lowest-cost access path by comparing <strong>sequential scans</strong> with eligible <strong>index scans</strong>, pushing down all single-table selection predicates whenever possible.</p><p>For joins, the optimizer incrementally builds <strong>left-deep join plans</strong> using explicit join predicates, evaluates available join algorithms, and excludes cartesian products.</p><p>The final execution plan is selected globally and completed by appending group-by and projection operators.</p><h2 id="concurrency-control" tabindex="-1">Concurrency Control <a class="header-anchor" href="#concurrency-control" aria-label="Permalink to &quot;Concurrency Control&quot;">​</a></h2><p>Designed and implemented a <strong>multi-granularity concurrency control subsystem</strong> based on strict two-phase locking (2PL) to support safe concurrent execution.</p><ul><li>Implemented <strong>LockManager</strong> with support for lock acquisition, release, promotion, and atomic acquire-and-release, and built hierarchical <strong>LockContext</strong> abstractions to enforce multi-granularity locking constraints across database, table, page, and record levels.</li><li>Implemented <strong>intent locks (IS, IX)</strong> alongside shared and exclusive locks (<strong>S, X</strong>), including correct handling of <strong>SIX locks</strong>, and lock propagation rules.</li><li>Integrated <strong>strict two-phase locking</strong> by acquiring locks during query execution and releasing all locks only at transaction completion, ensuring serializability.</li></ul><p>Together, these components provide correctness, isolation, and improved concurrency while maintaining modular separation between locking, execution, and storage layers.</p><h2 id="recovery" tabindex="-1">Recovery <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recovery&quot;">​</a></h2><p>Implemented an <strong>ARIES-style recovery manager</strong> to ensure atomicity and durability across system crashes.</p><ul><li>Reconstructed the <strong>transaction table</strong> and <strong>dirty page table</strong> during the analysis phase by scanning the log from the most recent checkpoint and correctly handling fuzzy checkpoint semantics.</li><li>Implemented <strong>redo logic with pageLSN validation</strong>, reapplying only necessary operations from the lowest recLSN to avoid redundant I/O.</li><li>Built a <strong>priority-based undo mechanism</strong> that rolls back incomplete transactions in descending LSN order using <strong>compensation log records (CLRs)</strong>.</li></ul><p>These mechanisms restore the database to a consistent state after failures while minimizing recovery overhead.</p><h2 id="limitations-future-work" tabindex="-1">Limitations &amp; Future Work <a class="header-anchor" href="#limitations-future-work" aria-label="Permalink to &quot;Limitations &amp; Future Work&quot;">​</a></h2><ul><li>Cost-based query optimization can be further improved.</li><li>Support for additional isolation levels (e.g., MVCC).</li><li>Enhanced recovery performance under high-concurrency workloads.</li></ul>',36)])])}const h=a(o,[["render",s]]);export{m as __pageData,h as default};
